// Names the country of a NASA FIRMS detection from its coordinates, using the
// borders of every country the FIRMS monitored boxes touch
// (scripts/shared/firms-region-borders.data.mjs, generated by
// scripts/generate-firms-region-borders.mjs from the Natural Earth 1:50m map).
//
// A point on land is in the country whose border contains it. A point at sea
// (an offshore platform's gas flare, or a coast the 1:50m map cuts off)
// belongs to the nearest coast within 200 nautical miles, the equidistance
// rule most maritime boundaries in these seas follow. Farther out is null.

import borders from './firms-region-borders.data.mjs';
import {
  KM_PER_DEG_LAT,
  KM_PER_DEG_LON_EQUATOR,
  borderPolygonContains,
  borderRingDistanceSq,
  buildBorderPolygon,
  decodeBorderArcs,
} from './cii-country-borders.mjs';

/** Exclusive economic zone limit: 200 nautical miles. */
export const FIRMS_OFFSHORE_LIMIT_KM = 370.4;

const ARCS = decodeBorderArcs(borders);
const POLYGONS = Object.entries(borders.countries)
  .flatMap(([code, polygons]) => polygons.map((polygon) => buildBorderPolygon(code, polygon, ARCS)));
const NAMES = borders.names;

/** ISO2 codes of the countries the border file names, sorted. */
export const FIRMS_BORDER_COUNTRIES = Object.freeze(Object.keys(borders.countries).sort());

function countryResult(code) {
  return { code, name: NAMES[code] };
}

/**
 * The country at (lat, lon) as `{ code, name }` (ISO2 and English name), or
 * null when the point is not a number or lies more than 200 nautical miles
 * from every coast in the border file.
 */
export function firmsCountryAt(lat, lon) {
  if (typeof lat !== 'number' || typeof lon !== 'number' || !Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return null;
  for (const polygon of POLYGONS) {
    if (borderPolygonContains(polygon, lon, lat)) return countryResult(polygon.code);
  }
  const ky = KM_PER_DEG_LAT;
  const kx = KM_PER_DEG_LON_EQUATOR * Math.max(0.01, Math.cos((lat * Math.PI) / 180));
  const marginLat = FIRMS_OFFSHORE_LIMIT_KM / ky;
  const marginLon = FIRMS_OFFSHORE_LIMIT_KM / kx;
  let bestCode = null;
  let bestDistanceSq = FIRMS_OFFSHORE_LIMIT_KM * FIRMS_OFFSHORE_LIMIT_KM;
  for (const polygon of POLYGONS) {
    if (lat < polygon.minLat - marginLat || lat > polygon.maxLat + marginLat) continue;
    for (const x of [lon, lon + 360, lon - 360]) {
      if (x < polygon.minLon - marginLon || x > polygon.maxLon + marginLon) continue;
      for (const ring of polygon.rings) {
        const d = borderRingDistanceSq(ring, x, lat, kx, ky);
        if (d < bestDistanceSq) {
          bestDistanceSq = d;
          bestCode = polygon.code;
        }
      }
    }
  }
  return bestCode ? countryResult(bestCode) : null;
}
